
import type { BuyerDeliveryInputRequirementResource } from './BuyerDeliveryInputRequirementResource.js';
import type { BuyerDeliveryOptionResource } from './BuyerDeliveryOptionResource.js';
import type { DeliveryAddressAdvisoryResource } from './DeliveryAddressAdvisoryResource.js';
import type { DeliveryQuoteLineItemResource } from './DeliveryQuoteLineItemResource.js';

export type BuyerDeliveryQuoteChoiceGroupResource = { /** Buyer-actionable address verification results that affected this choice group. A suggested_address is an explicit correction the buyer may confirm; Flint does not apply it silently. */ "address_advisories"?: Array<DeliveryAddressAdvisoryResource>; "availability_status": "ready" | "needs_input" | "needs_checkout_context" | "unavailable" | (string & {}); "delivery_choice_group_id": string; "evaluation_status": "complete" | "incomplete" | "degraded" | (string & {}); "input_requirements": Array<BuyerDeliveryInputRequirementResource>; "line_items": Array<DeliveryQuoteLineItemResource>; /** Types of the delivery methods that can serve this group's items, each listed once, in the order the methods display. A type is listed before its options are priced, such as a local delivery that waits for the buyer's address, and stays listed while its methods need more input or cannot serve the current input. options lists what the buyer can choose now. A method whose type these items do not allow is left out, and the list is empty when no method can serve them. */ "method_types": Array<"shipment" | "pickup" | "local_delivery" | (string & {})>; "options": Array<BuyerDeliveryOptionResource>; "previously_selected_delivery_method_id"?: string; "stable_key": string; };
